const width=w=>{const n=Math.max(230,Math.min(430,w));document.documentElement.style.setProperty('--side',n+'px');store.set('fallacies-side',n)};
const sw=store.get('fallacies-side',300);if(typeof sw==='number'&&Number.isFinite(sw))width(sw);
$('#resizer').addEventListener('pointerdown',e=>{e.preventDefault();$('#resizer').setPointerCapture(e.pointerId);document.body.classList.add('resizing');const move=e=>width(innerWidth-e.clientX);const end=()=>{document.body.classList.remove('resizing');$('#resizer').removeEventListener('pointermove',move);$('#resizer').removeEventListener('pointerup',end);$('#resizer').removeEventListener('pointercancel',end)};$('#resizer').addEventListener('pointermove',move);$('#resizer').addEventListener('pointerup',end);$('#resizer').addEventListener('pointercancel',end)});$('#resizer').onkeydown=e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();width($('#sidebar').offsetWidth+(e.key==='ArrowLeft'?10:-10))}};
